//! Bounded, loopback-only runtime telemetry for local tools.
//!
//! Samples are in-memory JSON values. No voxel arrays are generated by this
//! module; publishers should send compact metrics and object summaries.

use serde_json::{json, Value};
use std::{
    collections::VecDeque,
    fs,
    io::{self, BufRead, BufReader, Read, Write},
    net::{IpAddr, Shutdown, SocketAddr, TcpListener, TcpStream},
    path::{Path, PathBuf},
    process,
    sync::{Arc, Condvar, Mutex, OnceLock},
    thread,
    time::{Duration, SystemTime, UNIX_EPOCH},
};

const CAPACITY: usize = 1024;
const MAX_LINE: usize = 64 * 1024;
const MAX_SAMPLE_BYTES: usize = 48 * 1024;
const DISCOVERY: &str = ".voxel-runtime.json";
static ACTIVE_SERVERS: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

#[derive(Clone)]
struct Sample {
    sequence: u64,
    timestamp_ms: u128,
    topic: String,
    data: Value,
}

#[derive(Default)]
struct Ring {
    next: u64,
    samples: VecDeque<Sample>,
}

fn ring() -> &'static (Mutex<Ring>, Condvar) {
    static RING: OnceLock<(Mutex<Ring>, Condvar)> = OnceLock::new();
    RING.get_or_init(|| (Mutex::new(Ring::default()), Condvar::new()))
}

/// Publish a compact JSON telemetry sample to the process-local bounded ring.
pub fn publish(topic: &str, data: Value) {
    if topic.is_empty() || topic.len() > 128 {
        return;
    }
    if serde_json::to_vec(&data).map_or(true, |encoded| encoded.len() > MAX_SAMPLE_BYTES) {
        return;
    }
    let (lock, cv) = ring();
    if let Ok(mut state) = lock.lock() {
        let sequence = state.next.saturating_add(1);
        state.next = sequence;
        let timestamp_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis();
        if state.samples.len() == CAPACITY {
            state.samples.pop_front();
        }
        state.samples.push_back(Sample {
            sequence,
            timestamp_ms,
            topic: topic.to_owned(),
            data,
        });
        cv.notify_all();
    }
}

#[derive(Clone, Debug)]
struct Discovery {
    address: SocketAddr,
    session_id: String,
    pid: u32,
    root: String,
}

/// Owns the local metrics listener and removes only its matching discovery file.
pub struct RuntimeMetricsServer {
    root: PathBuf,
    discovery: Discovery,
    stop: Arc<Mutex<bool>>,
    worker: Option<thread::JoinHandle<()>>,
}

/// Returns whether this process currently owns a live telemetry server.
pub fn is_active() -> bool {
    ACTIVE_SERVERS.load(std::sync::atomic::Ordering::Acquire) > 0
}

fn unique_session() -> String {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    format!(
        "{:x}-{:x}-{:x}",
        process::id(),
        nanos,
        (&nanos as *const u128 as usize)
    )
}

/// Start the loopback server and publish its versioned discovery descriptor.
pub fn start_server(project_root: &Path) -> io::Result<RuntimeMetricsServer> {
    fs::create_dir_all(project_root)?;
    let root = fs::canonicalize(project_root)?;
    let path = root.join(DISCOVERY);
    if path.exists() {
        let old_bytes = fs::read(&path)?;
        if old_bytes.len() > 4096 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "existing runtime discovery is too large",
            ));
        }
        let old: Value = serde_json::from_slice(&old_bytes).map_err(|e| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("unrecognized runtime discovery: {e}"),
            )
        })?;
        let old_root = old.get("root").and_then(Value::as_str).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "runtime discovery has no root")
        })?;
        if old_root != root.to_string_lossy() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "runtime discovery belongs to another project root",
            ));
        }
        let old_pid = old.get("pid").and_then(Value::as_u64).ok_or_else(|| {
            io::Error::new(io::ErrorKind::InvalidData, "runtime discovery has no pid")
        })?;
        let old_session = old
            .get("session_id")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "runtime discovery has no session",
                )
            })?;
        let old_address = old
            .get("address")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "runtime discovery has no address",
                )
            })?
            .parse::<SocketAddr>()
            .map_err(|_| {
                io::Error::new(
                    io::ErrorKind::InvalidData,
                    "runtime discovery has invalid address",
                )
            })?;
        if old.get("version").and_then(Value::as_u64) != Some(1)
            || old_pid > u32::MAX as u64
            || old_session.is_empty()
            || !old_address.ip().is_loopback()
        {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "runtime discovery has unsupported or unsafe fields",
            ));
        }
        // A valid response proves the endpoint is still owned. Do not replace it.
        if probe_discovery(old_address, old_session, old_pid as u32, old_root) {
            return Err(io::Error::new(
                io::ErrorKind::AddrInUse,
                "runtime metrics server already active for this project",
            ));
        }
        // Only remove the exact stale descriptor we inspected; concurrent replacement wins.
        if fs::read(&path)? != old_bytes {
            return Err(io::Error::new(
                io::ErrorKind::AddrInUse,
                "runtime discovery changed during stale check",
            ));
        }
        fs::remove_file(&path)?;
    }
    let listener = TcpListener::bind(("127.0.0.1", 0))?;
    listener.set_nonblocking(true)?;
    let discovery = Discovery {
        address: listener.local_addr()?,
        session_id: unique_session(),
        pid: process::id(),
        root: root.to_string_lossy().into_owned(),
    };
    let descriptor = json!({"version":1,"pid":discovery.pid,"address":discovery.address.to_string(),"session_id":discovery.session_id,"root":discovery.root});
    let tmp = root.join(format!("{DISCOVERY}.{}.tmp", discovery.pid));
    fs::write(
        &tmp,
        serde_json::to_vec(&descriptor).map_err(io::Error::other)?,
    )?;
    if let Err(error) = fs::rename(&tmp, &path) {
        let _ = fs::remove_file(&tmp);
        return Err(error);
    }

    let stop = Arc::new(Mutex::new(false));
    let worker_stop = Arc::clone(&stop);
    let server_discovery = discovery.clone();
    let worker = thread::Builder::new()
        .name("voxel-runtime-metrics".into())
        .spawn(move || {
            // Four bounded workers prevent slow long-polls from blocking status requests.
            let permits = Arc::new((Mutex::new(0usize), Condvar::new()));
            while !*worker_stop.lock().unwrap_or_else(|e| e.into_inner()) {
                match listener.accept() {
                    Ok((stream, _)) => {
                        let permit = Arc::clone(&permits);
                        let session = server_discovery.clone();
                        thread::spawn(move || {
                            let (lock, cv) = &*permit;
                            let Ok(mut count) = lock.lock() else {
                                return;
                            };
                            if *count >= 4 {
                                let _ = stream.shutdown(Shutdown::Both);
                                return;
                            }
                            *count += 1;
                            drop(count);
                            handle_client(stream, &session);
                            if let Ok(mut count) = lock.lock() {
                                *count -= 1;
                                cv.notify_one();
                            }
                        });
                    }
                    Err(e) if e.kind() == io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(10))
                    }
                    Err(_) => thread::sleep(Duration::from_millis(50)),
                }
            }
        })?;
    ACTIVE_SERVERS.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
    Ok(RuntimeMetricsServer {
        root,
        discovery,
        stop,
        worker: Some(worker),
    })
}

impl Drop for RuntimeMetricsServer {
    fn drop(&mut self) {
        ACTIVE_SERVERS.fetch_sub(1, std::sync::atomic::Ordering::AcqRel);
        if let Ok(mut stop) = self.stop.lock() {
            *stop = true;
        }
        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
        let path = self.root.join(DISCOVERY);
        if let Ok(bytes) = fs::read(&path) {
            let matches = serde_json::from_slice::<Value>(&bytes)
                .ok()
                .is_some_and(|v| {
                    v.get("session_id").and_then(Value::as_str) == Some(&self.discovery.session_id)
                        && v.get("pid").and_then(Value::as_u64) == Some(self.discovery.pid as u64)
                });
            if matches {
                let _ = fs::remove_file(path);
            }
        }
    }
}

fn handle_client(mut stream: TcpStream, discovery: &Discovery) {
    let _ = stream.set_read_timeout(Some(Duration::from_secs(2)));
    let _ = stream.set_write_timeout(Some(Duration::from_secs(2)));
    let cloned = match stream.try_clone() {
        Ok(s) => s,
        Err(_) => return,
    };
    let reader = BufReader::new(cloned);
    let mut line = Vec::new();
    if reader
        .take((MAX_LINE + 1) as u64)
        .read_until(b'\n', &mut line)
        .is_err()
        || line.len() > MAX_LINE
    {
        return;
    }
    let response = match serde_json::from_slice::<Value>(&line) {
        Ok(req) => serve(&req, discovery),
        Err(_) => error_response(discovery, "invalid_request"),
    };
    if let Ok(mut bytes) = serde_json::to_vec(&response) {
        if bytes.len() <= MAX_LINE {
            bytes.push(b'\n');
            let _ = stream.write_all(&bytes);
        }
    }
}

fn error_response(d: &Discovery, error: &str) -> Value {
    json!({"ok":false,"error":error,"pid":d.pid,"session_id":d.session_id,"root":d.root})
}

fn compact_data(topic: &str, data: &Value) -> Value {
    if topic == "objects" {
        let count = data
            .get("component_count")
            .and_then(Value::as_u64)
            .or_else(|| {
                data.pointer("/topology/component_count")
                    .and_then(Value::as_u64)
            })
            .or_else(|| data.pointer("/components/emitted").and_then(Value::as_u64))
            .or_else(|| {
                data.pointer("/components/items")
                    .and_then(Value::as_array)
                    .map(|a| a.len() as u64)
            })
            .or_else(|| {
                data.get("components")
                    .and_then(Value::as_array)
                    .map(|a| a.len() as u64)
            });
        return json!({"component_count":count,"truncated":true});
    }
    if serde_json::to_vec(data).map_or(false, |bytes| bytes.len() > 12 * 1024) {
        return json!({"truncated":true,"original_bytes":serde_json::to_vec(data).map_or(0,|b|b.len())});
    }
    data.clone()
}

fn serve(req: &Value, d: &Discovery) -> Value {
    if req.get("session_id").and_then(Value::as_str) != Some(&d.session_id) {
        return error_response(d, "session_mismatch");
    }
    let command = req.get("command").and_then(Value::as_str).unwrap_or("");
    if command == "status" {
        let (lock, _) = ring();
        let Ok(state) = lock.lock() else {
            return error_response(d, "busy");
        };
        let mut latest = serde_json::Map::new();
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis();
        for s in state.samples.iter().rev() {
            if latest.contains_key(&s.topic) {
                continue;
            }
            latest.insert(s.topic.clone(), json!({"sequence":s.sequence,"timestamp_ms":s.timestamp_ms,"age_ms":now.saturating_sub(s.timestamp_ms),"data":compact_data(&s.topic,&s.data)}));
        }
        while serde_json::to_vec(&json!({"ok":true,"pid":d.pid,"session_id":d.session_id,"root":d.root,"latest":latest,"latest_sequence":state.next})).map_or(true, |b| b.len() > MAX_LINE - 1) {
            let Some(key) = latest.keys().next().cloned() else { break; };
            latest.remove(&key);
        }
        return json!({"ok":true,"pid":d.pid,"session_id":d.session_id,"root":d.root,"latest":latest,"latest_sequence":state.next});
    }
    if command == "objects" {
        let (lock, _) = ring();
        let Ok(state) = lock.lock() else {
            return error_response(d, "busy");
        };
        let object = state
            .samples
            .iter()
            .rev()
            .find(|s| s.topic == "objects")
            .map(|s| s.data.clone())
            .or_else(|| {
                state
                    .samples
                    .iter()
                    .rev()
                    .find(|s| s.topic == "physics")
                    .and_then(|s| {
                        s.data
                            .get("components")
                            .or_else(|| s.data.get("objects"))
                            .cloned()
                    })
            })
            .unwrap_or(Value::Null);
        return json!({"ok":true,"pid":d.pid,"session_id":d.session_id,"root":d.root,"objects":object});
    }
    if command != "read" && command != "metrics" {
        return error_response(d, "unknown_command");
    }
    let after = req
        .get("after_sequence")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let max = req.get("max_samples").and_then(Value::as_u64).unwrap_or(16);
    let wait_ms = req.get("wait_ms").and_then(Value::as_u64).unwrap_or(0);
    let topic = req.get("topic").and_then(Value::as_str);
    if !(1..=64).contains(&max) || wait_ms > 10_000 {
        return error_response(d, "bounds");
    }
    let (lock, cv) = ring();
    let Ok(mut state) = lock.lock() else {
        return error_response(d, "busy");
    };
    let has_match = |s: &Ring| {
        s.samples
            .iter()
            .any(|sample| sample.sequence > after && topic.is_none_or(|t| sample.topic == t))
    };
    if !has_match(&state) && wait_ms > 0 {
        let (s, _) = cv
            .wait_timeout_while(state, Duration::from_millis(wait_ms), |s| !has_match(s))
            .unwrap_or_else(|e| e.into_inner());
        state = s;
    }
    let earliest = state
        .samples
        .front()
        .map_or(state.next.saturating_add(1), |s| s.sequence);
    let gap = after.saturating_add(1) < earliest;
    let mut advanced = after;
    let mut samples = Vec::new();
    let candidates: Vec<&Sample> = state
        .samples
        .iter()
        .filter(|s| s.sequence > after && topic.is_none_or(|t| s.topic == t))
        .take(max as usize)
        .collect();
    let more_matching = state
        .samples
        .iter()
        .filter(|s| s.sequence > after && topic.is_none_or(|t| s.topic == t))
        .nth(max as usize)
        .is_some();
    let mut capped = false;
    for s in &candidates {
        let sample = json!({"sequence":s.sequence,"timestamp_ms":s.timestamp_ms,"topic":s.topic,"data":compact_data(&s.topic,&s.data)});
        let mut trial = samples.clone();
        trial.push(sample.clone());
        let projected = json!({"ok":true,"pid":d.pid,"session_id":d.session_id,"root":d.root,"samples":trial,"next_sequence":s.sequence,"latest_sequence":state.next,"earliest_sequence":earliest,"gap":gap,"lost_samples":if gap {earliest.saturating_sub(after.saturating_add(1))} else {0},"has_more":true});
        if serde_json::to_vec(&projected).map_or(true, |b| b.len() > MAX_LINE - 1) {
            capped = true;
            break;
        }
        advanced = s.sequence;
        samples.push(sample);
    }
    if !capped && !more_matching {
        advanced = state.next;
    }
    let has_more = state
        .samples
        .iter()
        .any(|s| s.sequence > advanced && topic.is_none_or(|t| s.topic == t));
    json!({"ok":true,"pid":d.pid,"session_id":d.session_id,"root":d.root,"samples":samples,"next_sequence":advanced,"latest_sequence":state.next,"earliest_sequence":earliest,"gap":gap,"lost_samples":if gap {earliest.saturating_sub(after.saturating_add(1))} else {0},"has_more":has_more})
}

fn probe_discovery(address: SocketAddr, session: &str, pid: u32, root: &str) -> bool {
    let Ok(mut stream) = TcpStream::connect_timeout(&address, Duration::from_millis(350)) else {
        return false;
    };
    let _ = stream.set_read_timeout(Some(Duration::from_millis(500)));
    let _ = stream.set_write_timeout(Some(Duration::from_millis(350)));
    let request = json!({"command":"status","session_id":session});
    let Ok(mut request) = serde_json::to_vec(&request) else {
        return false;
    };
    request.push(b'\n');
    if stream.write_all(&request).is_err() {
        return false;
    }
    let mut line = Vec::new();
    if BufReader::new(stream)
        .take((MAX_LINE + 1) as u64)
        .read_until(b'\n', &mut line)
        .is_err()
        || line.len() > MAX_LINE
    {
        return false;
    }
    let Ok(response) = serde_json::from_slice::<Value>(&line) else {
        return false;
    };
    response.get("ok").and_then(Value::as_bool) == Some(true)
        && response.get("pid").and_then(Value::as_u64) == Some(pid as u64)
        && response.get("session_id").and_then(Value::as_str) == Some(session)
        && response.get("root").and_then(Value::as_str) == Some(root)
}

/// Query the server discovered under this project root, validating its identity.
pub fn query_runtime(project_root: &Path, request: &Value) -> Result<Value, String> {
    let path = project_root.join(DISCOVERY);
    let expected_root = fs::canonicalize(project_root).map_err(|e| format!("project root: {e}"))?;
    let bytes = fs::read(&path).map_err(|e| format!("discovery: {e}"))?;
    if bytes.len() > 4096 {
        return Err("discovery too large".into());
    }
    let v: Value = serde_json::from_slice(&bytes).map_err(|e| format!("discovery JSON: {e}"))?;
    if v.get("version").and_then(Value::as_u64) != Some(1) {
        return Err("unsupported discovery version".into());
    }
    let pid_value = v.get("pid").and_then(Value::as_u64).ok_or("missing pid")?;
    if pid_value == 0 || pid_value > u32::MAX as u64 {
        return Err("invalid process id in discovery".into());
    }
    let pid = pid_value as u32;
    let session = v
        .get("session_id")
        .and_then(Value::as_str)
        .ok_or("missing session_id")?;
    if v.get("root").and_then(Value::as_str) != Some(expected_root.to_string_lossy().as_ref()) {
        return Err("project root mismatch".into());
    }
    let address: SocketAddr = v
        .get("address")
        .and_then(Value::as_str)
        .ok_or("missing address")?
        .parse()
        .map_err(|_| "invalid address")?;
    if !matches!(address.ip(), IpAddr::V4(ip) if ip.is_loopback())
        && !matches!(address.ip(), IpAddr::V6(ip) if ip.is_loopback())
    {
        return Err("address is not loopback".into());
    }
    let mut req = request.clone();
    if !req.is_object() {
        return Err("request must be an object".into());
    }
    req["session_id"] = Value::String(session.to_owned());
    let mut bytes = serde_json::to_vec(&req).map_err(|e| e.to_string())?;
    if bytes.len() + 1 > MAX_LINE {
        return Err("request too large".into());
    }
    bytes.push(b'\n');
    let mut stream = TcpStream::connect_timeout(&address, Duration::from_secs(2))
        .map_err(|e| format!("connect: {e}"))?;
    stream
        .set_read_timeout(Some(Duration::from_secs(12)))
        .map_err(|e| e.to_string())?;
    stream
        .set_write_timeout(Some(Duration::from_secs(2)))
        .map_err(|e| e.to_string())?;
    stream.write_all(&bytes).map_err(|e| e.to_string())?;
    let reader = BufReader::new(stream);
    let mut line = Vec::new();
    reader
        .take((MAX_LINE + 1) as u64)
        .read_until(b'\n', &mut line)
        .map_err(|e| e.to_string())?;
    if line.len() > MAX_LINE {
        return Err("response too large".into());
    }
    let response: Value =
        serde_json::from_slice(&line).map_err(|e| format!("response JSON: {e}"))?;
    if response.get("pid").and_then(Value::as_u64) != Some(pid as u64)
        || response.get("session_id").and_then(Value::as_str) != Some(session)
        || response.get("root").and_then(Value::as_str)
            != Some(expected_root.to_string_lossy().as_ref())
    {
        return Err("response identity mismatch".into());
    }
    Ok(response)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicUsize, Ordering};
    static NEXT: AtomicUsize = AtomicUsize::new(0);
    fn root() -> PathBuf {
        let p = PathBuf::from(format!(
            "E:/voxel-runtime-metrics-test-{}-{}",
            process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = fs::remove_dir_all(&p);
        p
    }
    fn query(root: &Path, command: &str) -> Value {
        query_runtime(root, &json!({"command":command})).unwrap()
    }

    #[test]
    fn cursor_gap_and_bounds_are_reported() {
        let root = root();
        let server = start_server(&root).unwrap();
        for n in 0..CAPACITY + 5 {
            publish("test_ring", json!({"n":n}));
        }
        let d = &server.discovery;
        let r = serve(
            &json!({"command":"read","session_id":d.session_id,"after_sequence":0,"max_samples":64}),
            d,
        );
        assert_eq!(r["samples"].as_array().unwrap().len(), 64);
        let earliest = r["earliest_sequence"].as_u64().unwrap();
        assert_eq!(r["gap"], earliest > 1);
        assert_eq!(r["lost_samples"], earliest.saturating_sub(1));
        assert_eq!(
            serve(
                &json!({"command":"read","session_id":d.session_id,"max_samples":65}),
                d
            )["error"],
            "bounds"
        );
        drop(server);
        let _ = fs::remove_dir_all(root);
    }
    #[test]
    fn long_poll_wakes_when_a_matching_sample_is_published() {
        let root = root();
        let server = start_server(&root).unwrap();
        let after = ring().0.lock().unwrap().next;
        let d = server.discovery.clone();
        let t = thread::spawn(move || {
            serve(
                &json!({"command":"read","session_id":d.session_id,"after_sequence":after,"wait_ms":5000}),
                &d,
            )
        });
        thread::sleep(Duration::from_millis(30));
        publish("long_poll_wakeup_test", json!({"value":42}));
        let started = std::time::Instant::now();
        let response = t.join().unwrap();
        assert!(started.elapsed() < Duration::from_secs(1));
        assert!(!response["samples"].as_array().unwrap().is_empty());
        drop(server);
        let _ = fs::remove_dir_all(root);
    }
    #[test]
    fn long_poll_times_out_when_no_sample_arrives() {
        let root = root();
        let server = start_server(&root).unwrap();
        let after = ring().0.lock().unwrap().next;
        let d = server.discovery.clone();
        let t = thread::spawn(move || {
            serve(
                &json!({"command":"read","session_id":d.session_id,"after_sequence":after,"topic":"long_poll_timeout_test","wait_ms":120}),
                &d,
            )
        });
        let started = std::time::Instant::now();
        thread::sleep(Duration::from_millis(20));
        publish("unrelated_long_poll_test", json!({"ignored":true}));
        let response = t.join().unwrap();
        assert!(started.elapsed() >= Duration::from_millis(80));
        assert!(response["samples"].as_array().unwrap().is_empty());
        drop(server);
        let _ = fs::remove_dir_all(root);
    }
    #[test]
    fn filtered_read_advances_past_nonmatching_samples() {
        let root = root();
        let server = start_server(&root).unwrap();
        let after = ring().0.lock().unwrap().next;
        publish("filtered_read_other", json!({"n":1}));
        let d = &server.discovery;
        let response = serve(
            &json!({"command":"read","session_id":d.session_id,"after_sequence":after,"topic":"filtered_read_target"}),
            d,
        );
        assert!(response["samples"].as_array().unwrap().is_empty());
        assert_eq!(response["next_sequence"], response["latest_sequence"]);
        drop(server);
        let _ = fs::remove_dir_all(root);
    }
    #[test]
    fn discovery_validates_and_drop_removes_only_matching_file() {
        let root = root();
        let server = start_server(&root).unwrap();
        assert_eq!(query(&root, "status")["ok"], true);
        let p = root.join(DISCOVERY);
        let original = fs::read(&p).unwrap();
        let mut stale: Value = serde_json::from_slice(&original).unwrap();
        stale["pid"] = json!(0);
        fs::write(&p, serde_json::to_vec(&stale).unwrap()).unwrap();
        assert!(query_runtime(&root, &json!({"command":"status"})).is_err());
        drop(server);
        assert!(p.exists());
        let _ = fs::remove_dir_all(root);
    }
    #[test]
    fn query_accepts_server_pid_different_from_client_pid() {
        let root = root(); fs::create_dir_all(&root).unwrap();
        let canonical = fs::canonicalize(&root).unwrap();
        let listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let address = listener.local_addr().unwrap();
        let server_pid = if process::id() == u32::MAX { 1 } else { process::id() + 1 };
        let session = "mock-native-session";
        let descriptor = json!({"version":1,"pid":server_pid,"address":address.to_string(),"session_id":session,"root":canonical.to_string_lossy()});
        fs::write(canonical.join(DISCOVERY), serde_json::to_vec(&descriptor).unwrap()).unwrap();
        let response = json!({"ok":true,"pid":server_pid,"session_id":session,"root":canonical.to_string_lossy(),"latest":{},"latest_sequence":0});
        let server = thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let mut bytes = serde_json::to_vec(&response).unwrap(); bytes.push(b'\n');
            stream.write_all(&bytes).unwrap();
        });
        assert_ne!(server_pid, process::id());
        let result = query_runtime(&root, &json!({"command":"status"})).unwrap();
        assert_eq!(result["pid"], server_pid);
        assert_eq!(result["session_id"], session);
        server.join().unwrap();
        let _ = fs::remove_dir_all(root);
    }
    #[test]
    fn stale_discovery_is_recovered_but_active_and_unknown_files_are_preserved() {
        let root = root();
        fs::create_dir_all(&root).unwrap();
        let listener = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let address = listener.local_addr().unwrap();
        drop(listener);
        let canonical = fs::canonicalize(&root).unwrap();
        let path = canonical.join(DISCOVERY);
        fs::write(&path, serde_json::to_vec(&json!({"version":1,"pid":process::id(),"address":address.to_string(),"session_id":"stale-session","root":canonical.to_string_lossy()})).unwrap()).unwrap();
        let recovered = start_server(&root).unwrap();
        assert_ne!(recovered.discovery.session_id, "stale-session");
        drop(recovered);

        let active = start_server(&root).unwrap();
        assert_eq!(
            start_server(&root).err().unwrap().kind(),
            io::ErrorKind::AddrInUse
        );
        assert_eq!(
            query(&root, "status")["session_id"],
            active.discovery.session_id
        );
        drop(active);

        fs::write(&path, b"user-owned unknown data").unwrap();
        let before = fs::read(&path).unwrap();
        assert_eq!(
            start_server(&root).err().unwrap().kind(),
            io::ErrorKind::InvalidData
        );
        assert_eq!(fs::read(&path).unwrap(), before);
        let _ = fs::remove_dir_all(root);
    }
    #[test]
    fn session_and_command_bounds_are_enforced() {
        let root = root();
        let server = start_server(&root).unwrap();
        let d = &server.discovery;
        assert_eq!(
            serve(&json!({"command":"status","session_id":"wrong"}), d)["error"],
            "session_mismatch"
        );
        assert_eq!(
            serve(
                &json!({"command":"read","session_id":d.session_id,"wait_ms":10001}),
                d
            )["error"],
            "bounds"
        );
        drop(server);
        let _ = fs::remove_dir_all(root);
    }
}
